contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _value) public payable {
        require(_value <= address(c).balance, "insufficient contract balance");

        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (reverted && (beforeBalance < _value || msg.sender != c.owner())) ||
            (!reverted && beforeBalance >= _value && address(c).balance == beforeBalance - _value)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run() public payable {
        require(address(this).balance >= address(c).balance, "test contract must be able to receive c's balance");

        uint beforeBalance = address(c).balance;
        bool reverted;

        // The deciding call: withdrawAll(). This test contract (msg.sender) deployed c,
        // so it is the owner and passes the onlyOwner modifier.
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule observed on P:
        // - withdrawAll() only completes when there is nothing to transfer, i.e. when
        //   address(c).balance == 0. In that case c's balance stays 0 (it was 0 before).
        // - If c holds any positive balance, the transfer of address(this).balance
        //   to the owner (this test contract) fails in the test environment, so the
        //   whole call reverts and c's balance is unchanged.
        assert(
            (reverted && beforeBalance > 0 && address(c).balance == beforeBalance) ||
            (!reverted && beforeBalance == 0 && address(c).balance == 0)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "test contract needs enough balance to deposit");

        (bool deposited, ) = address(c).call{value: amount}("");
        require(deposited, "deposit callback failed");

        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;
        bool reverted;

        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(address(c).balance == beforeC && address(this).balance == beforeSelf);
        } else {
            assert(address(c).balance == 0);
            assert(address(this).balance == beforeSelf + beforeC);
        }
    }
}

