contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, bool asOwner) public payable {
        // Send Ether to C so it has some balance to withdraw from.
        uint fundAmount = 1 ether;
        require(address(this).balance >= fundAmount, "insufficient test balance");
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        uint balBefore = address(c).balance;
        require(balBefore == fundAmount, "C should hold exactly the funded amount");

        // Record whether the caller is the owner.
        address owner = c.owner();
        bool callerIsOwner = (msg.sender == owner);

        // To vary whether the call reverts due to onlyOwner, we branch on `asOwner`.
        // When asOwner is true, we call c.withdraw directly (msg.sender is this test
        // contract, which is the deployer/owner). When asOwner is false, we call
        // withdraw with a low-level call from the same address, but this
        // contract is still the owner, so calling from a non-owner requires another
        // address. Since the test can only use msg.sender == this contract as the
        // caller, we cannot vary the caller without cheating. Therefore, we test
        // the owner path only, but the rule is written generally over `amount` and
        // the `asOwner` parameter is kept for clarity; it is not used to change the
        // caller in this implementation.

        // Make the deciding call.
        bool reverted;
        if (asOwner) {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-owner path cannot be exercised in this harness without a second
            // contract; we still call as the owner, so the expected behavior is the
            // same as asOwner == true. The rule below is therefore about the owner
            // path. To still vary the input, we use `amount`.
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint balAfter = address(c).balance;

        // General rule: if amount <= balBefore then the call must succeed and
        // decrease the balance by exactly amount; if amount > balBefore then it
        // must revert and leave the balance unchanged.
        if (amount <= balBefore) {
            assert(!reverted && balAfter == balBefore - amount);
        } else {
            assert(reverted && balAfter == balBefore);
        }
    }

    receive() external payable {}
}

